        };
        let msg = err.to_string();
        assert!(msg.contains("node"));
        assert!(msg.contains("Install command exited with code 1"));
    }

    #[test]
    fn io_error_converts_from_std() {
        let io_err = std::io::Error::new(std::io::ErrorKind::NotFound, "file missing");
        let err: BivvyError = io_err.into();
        assert!(matches!(err, BivvyError::Io(_)));
    }

    #[test]
    fn result_type_alias_works() {
        fn returns_error() -> Result<()> {
            Err(BivvyError::ConfigValidationError {
                message: "test".into(),
            })
        }
        assert!(returns_error().is_err());
    }

    #[test]
    fn user_cancelled_displays_message() {
        let err = BivvyError::UserCancelled;
        assert!(err.to_string().contains("cancelled"));
    }

    #[test]
    fn user_cancelled_is_user_cancelled() {
        let err = BivvyError::UserCancelled;
        assert!(err.is_user_cancelled());
    }

    #[test]
    fn other_errors_are_not_user_cancelled() {
        let err = BivvyError::ConfigValidationError {
            message: "test".into(),
        };
        assert!(!err.is_user_cancelled());

        let io_err = BivvyError::Io(std::io::Error::new(
            std::io::ErrorKind::UnexpectedEof,
            "eof",
        ));
        assert!(!io_err.is_user_cancelled());
    }
}

